{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= k <= n <= 100000",
      "description": "The length of the string s is at least 1 and at most 100000, and the length of the minimal unique substring is at least 1 and at most n."
    },
    {
      "id": "P2",
      "expression": "(n mod 2) == (k mod 2)",
      "description": "The length of the string s and the length of the minimal unique substring are both even or both odd."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(s) == n",
      "description": "The output string s has the specified length n."
    },
    {
      "id": "Q2",
      "expression": "all(c in '01' for c in s)",
      "description": "Each character in the output string s is either '0' or '1'."
    },
    {
      "id": "Q3",
      "expression": "any(s[i:i+k] == s[i]*k for i in range(len(s) - k + 1))",
      "description": "The output string s contains at least one substring of length k that is composed of identical characters."
    },
    {
      "id": "Q4",
      "expression": "not any(s[i:i+k] != s[i]*k and s[i:i+k] in s[:i] for i in range(len(s) - k + 1))",
      "description": "The output string s does not contain any substring of length k that is not composed of identical characters and appears as a substring earlier in the string."
    }
  ],
  "invariants": []
}
